export function buildCategories(data) {
  const words = new Map(data.lexicon.map(([word, count, pos, forms]) => [normalize(word), { word, count, pos, aliases: forms }]));
  const categories = SETS.map(([id, pack, text, hint, gem, clever, list]) => {
    const entries = [...new Set(list.split('|'))].filter(w => !EXCLUDED.has(w));
    const answers = entries.map(word => { const item = words.get(normalize(word)); return { word, count: item?.count ?? null, aliases: [...(ALIASES[word] || []), ...(item?.aliases || [])] }; });
    return { id, pack, text, hint, answers, gem: entries.includes(gem) ? gem : entries.at(-1), clever: [clever], metric: 'corpus', source: 'Frecuencias de lemas españoles · OpenSubtitles / Spanish Data. Las voces sin dato se valoran editorialmente.' };
  });
  const makeGeo = (id, text, entries, gem, clever = [], hint = 'Nombres oficiales y variantes habituales') => ({ id, pack: 'spain', text, hint, answers: entries.map(([word, count]) => ({ word, count, aliases: REGION_ALIASES[word] || [] })), gem, clever, metric: 'population', source: 'INE · Padrón a 1 de enero de 2025, publicado en el BOE. Menor población = mayor rareza geográfica.' });
  const provinces = data.provinces.filter(([w]) => !['Ceuta', 'Melilla'].includes(w));
  categories.push(
    makeGeo('provinces', 'Nombra una provincia española.', provinces, 'Palencia', ['Soria']),
    makeGeo('capitals', 'Nombra una capital de provincia española.', data.capitals, 'Huesca', ['Teruel']),
    makeGeo('small-provinces', 'Nombra una provincia con menos de 500.000 habitantes.', provinces.filter(([, n]) => n < 500000), 'Lugo', ['Soria']),
    makeGeo('large-provinces', 'Nombra una provincia con más de un millón de habitantes.', provinces.filter(([, n]) => n > 1000000), 'Asturias'),
    makeGeo('small-capitals', 'Nombra una capital de provincia con menos de 150.000 habitantes.', data.capitals.filter(([, n]) => n < 150000), 'Pontevedra', ['Teruel']),
    makeGeo('large-capitals', 'Nombra una capital de provincia con más de 200.000 habitantes.', data.capitals.filter(([, n]) => n > 200000), 'Oviedo'),
    makeGeo('islands', 'Nombra una de las 11 islas que desglosa el Padrón del INE.', data.islands, 'Gomera, La', ['Hierro, El'], 'Baleares y Canarias · no se incluyen islotes'),
    makeGeo('canary-islands', 'Nombra una isla canaria desglosada en el Padrón del INE.', data.islands.filter(([w]) => !['Mallorca', 'Menorca', 'Ibiza', 'Formentera'].includes(w)), 'Palma, La', [], 'Las siete islas con desglose de población en esta tabla; La Graciosa figura con Lanzarote')
  );
  const animals = [...new Map(categories.filter(c => ['mammals', 'birds', 'fish', 'invertebrates', 'reptiles'].includes(c.id)).flatMap(c => c.answers).map(a => [normalize(a.word), a])).values()];
  for (const letter of ['a', 'b', 'c', 'm', 'p', 'r', 's', 't', 'z', 'ñ']) {
    const answers = animals.filter(a => normalize(a.word).includes(letter)).map(a => ({ ...a, aliases: a.aliases.filter(w => normalize(w).includes(letter)) }));
    if (answers.length >= 8) categories.push({ id: `animals-${letter === 'ñ' ? 'enye' : letter}`, pack: 'nature', text: `Nombra un animal cuyo nombre contenga la letra ${letter.toUpperCase()}.`, hint: 'Nombre común · singular · de nuestro repertorio de fauna', answers, gem: answers[Math.floor(answers.length * .7)].word, clever: [], metric: 'corpus', source: categories[0].source });
  }
  const addSubset = (baseId, id, text, predicate) => {
    const base = categories.find(c => c.id === baseId), answers = base.answers.filter(a => predicate(a.word));
    if (answers.length >= 8) categories.push({ ...base, id, text, answers: answers.map(a => ({ ...a, aliases: a.aliases.filter(predicate) })), gem: answers[Math.floor(answers.length * .7)].word, clever: [] });
  };
  addSubset('fruit', 'fruit-a', 'Nombra una fruta cuyo nombre contenga la letra A.', w => normalize(w).includes('a'));
  addSubset('jobs', 'jobs-c', 'Nombra una profesión que empiece por C.', w => normalize(w).startsWith('c'));
  addSubset('jobs', 'jobs-p', 'Nombra una profesión que empiece por P.', w => normalize(w).startsWith('p'));
  addSubset('colors', 'long-colors', 'Nombra un color de siete letras o más.', w => w.length >= 7);
  addSubset('food', 'food-a', 'Nombra un plato español que empiece por A.', w => normalize(w).startsWith('a'));
  addSubset('instruments', 'wind-instruments', 'Nombra un instrumento de viento.', w => ['flauta', 'trompeta', 'trombón', 'trompa', 'tuba', 'clarinete', 'oboe', 'fagot', 'saxofón', 'armónica', 'órgano', 'gaita', 'dulzaina', 'chirimía', 'alboka', 'txistu', 'cornamusa', 'ocarina', 'quena', 'zampoña', 'didyeridú', 'duduk', 'shakuhachi', 'flauta travesera'].includes(w));
  addSubset('instruments', 'string-instruments', 'Nombra un instrumento de cuerda.', w => ['guitarra', 'piano', 'violín', 'bajo', 'violonchelo', 'contrabajo', 'viola', 'arpa', 'clave', 'clavicordio', 'espineta', 'guitarrón', 'bandurria', 'laúd', 'timple', 'charango', 'ukelele', 'banjo', 'mandolina', 'sitar', 'sarod', 'balalaica', 'bouzouki', 'cítara', 'salterio', 'rabel', 'zanfona', 'nyckelharpa'].includes(w));
  addSubset('instruments', 'percussion', 'Nombra un instrumento de percusión.', w => ['batería', 'marimba', 'xilófono', 'vibráfono', 'glockenspiel', 'celesta', 'timbal', 'tambor', 'caja', 'bombo', 'pandereta', 'pandero', 'castañuelas', 'cajón', 'djembe', 'conga', 'bongó', 'güiro', 'maracas', 'triángulo', 'campana', 'gong', 'crótalo', 'kalimba', 'mbira', 'batería electrónica'].includes(w));
  for (const [suffix, label, predicate] of [
    ['r', 'que contenga la letra R', w => normalize(w).includes('r')],
    ['a', 'que contenga la letra A', w => normalize(w).includes('a')],
    ['o', 'que contenga la letra O', w => normalize(w).includes('o')]
  ]) {
    addSubset('provinces', `provinces-${suffix}`, `Nombra una provincia española ${label}.`, predicate);
    addSubset('capitals', `capitals-${suffix}`, `Nombra una capital de provincia española ${label}.`, predicate);
  }
  const lexical = (id, text, predicate, gem, pos) => {
    const answers = data.lexicon.filter(([w, , p]) => (!pos || p === pos) && predicate(w)).map(([word, count]) => ({ word, count, aliases: [] }));
    const existing = answers.find(a => normalize(a.word) === normalize(gem));
    if (!predicate(gem)) throw new Error(`Invalid curated gem for ${id}: ${gem}`);
    // A human-chosen, dictionary-valid gem may be absent from the frequency sample.
    if (!existing) answers.push({ word: gem, count: null, aliases: [] });
    if (answers.length < 8) return;
    categories.push({ id, pack: 'words', text, hint: pos === 'v' ? 'Solo infinitivos del repertorio' : 'Forma de diccionario: singular o infinitivo. Sin nombres propios.', answers, gem, clever: [], metric: 'corpus', source: 'Lemas de Spanish Data / OpenSubtitles y una joya revisada editorialmente. Las tildes no son obligatorias; la ñ sí cuenta.' });
  };
  lexical('letter-enye', 'Nombra una palabra que contenga la letra ñ.', w => w.includes('ñ'), 'alimaña');
  lexical('letter-x', 'Nombra una palabra que contenga la letra x.', w => w.includes('x'), 'exequias');
  lexical('letter-z', 'Nombra una palabra que contenga la letra z.', w => w.includes('z'), 'azabache');
  lexical('letter-j', 'Nombra una palabra que contenga la letra j.', w => w.includes('j'), 'aljibe');
  lexical('double-r', 'Nombra una palabra que contenga rr.', w => w.includes('rr'), 'zurrón');
  lexical('double-l', 'Nombra una palabra que contenga ll.', w => w.includes('ll'), 'aldabilla');
  lexical('five-letters', 'Nombra una palabra de cinco letras.', w => [...w].length === 5, 'ámbar');
  lexical('eight-letters', 'Nombra una palabra de ocho letras.', w => [...w].length === 8, 'azabache');
  lexical('long-words', 'Nombra una palabra de diez letras o más.', w => [...w].length >= 10, 'inmarcesible');
  lexical('ending-cion', 'Nombra una palabra que termine en -ción.', w => w.endsWith('ción'), 'abstracción');
  lexical('ending-dad', 'Nombra una palabra que termine en -dad.', w => w.endsWith('dad'), 'otredad');
  lexical('ending-mente', 'Nombra una palabra que termine en -mente.', w => w.endsWith('mente'), 'tácitamente');
  lexical('ending-ismo', 'Nombra una palabra que termine en -ismo.', w => w.endsWith('ismo'), 'atavismo');
  lexical('verbs-ar', 'Nombra un verbo que termine en -ar.', w => w.endsWith('ar'), 'pergeñar', 'v');
  lexical('verbs-er', 'Nombra un verbo que termine en -er.', w => w.endsWith('er'), 'tañer', 'v');
  lexical('verbs-ir', 'Nombra un verbo que termine en -ir.', w => w.endsWith('ir'), 'balbucir', 'v');
  lexical('start-a', 'Nombra un sustantivo que empiece por A.', w => normalize(w).startsWith('a'), 'alfeñique', 'n');
  lexical('start-b', 'Nombra un sustantivo que empiece por B.', w => w.startsWith('b'), 'badila', 'n');
  lexical('start-c', 'Nombra un sustantivo que empiece por C.', w => w.startsWith('c'), 'cachivache', 'n');
  lexical('start-m', 'Nombra un sustantivo que empiece por M.', w => w.startsWith('m'), 'marmita', 'n');
  lexical('start-p', 'Nombra un sustantivo que empiece por P.', w => w.startsWith('p'), 'palimpsesto', 'n');
  lexical('start-s', 'Nombra un sustantivo que empiece por S.', w => w.startsWith('s'), 'sotana', 'n');
  lexical('start-t', 'Nombra un sustantivo que empiece por T.', w => w.startsWith('t'), 'tahalí', 'n');
  lexical('vowel-bookends', 'Nombra una palabra que empiece y termine en vocal.', w => /^[aáeéiíoóuú].*[aáeéiíoóuú]$/.test(w), 'albedrío');
  categories.forEach(c => { c.legacy = true; c.dataVersion = LEGACY_VERSION; });
  const previous = buildSpainCategories(data, categories);
  previous.forEach(c => { c.legacy = true; c.dataVersion = PREVIOUS_VERSION; });
  return [...categories, ...previous, ...buildCuratedCategories(data, previous)];
}
